let LANG=(()=>{ try{ return localStorage.getItem("hi75c-lang")||"en"; }catch(e){ return "en"; } })();
function T(s){ return LANG==="en"?(I18N[s]||s):s; }
function applyStatic(){
  document.documentElement.lang=LANG; document.documentElement.dir=LANG==="en"?"ltr":"rtl";
  const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest("script,style,#kb,#grid,#changes,#log,#cats")?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
  let n; while(n=w.nextNode()){ if(n.__ar===undefined){ const k=n.textContent.trim(); if(I18N[k]) n.__ar=k; else continue; }
    n.textContent=n.textContent.replace(n.textContent.trim(),T(n.__ar)); }
  document.getElementById("btnLang").textContent=LANG==="en"?"عربي":"English";
}
/* =====================================================================
   LEOBOG Hi75C Pro (Sinowealth 258a:010c) — protocol decoded from
   LEOBOG ONE USB captures.
   Keymap write = 4 × SET_FEATURE report 6 (520 bytes incl. id):
     [06][03][chunk 0..3][00][mode][00][00][02] + 127 entries × 4 B + [5a a5]
   chunk 0 = base layer, chunk 1 = Fn layer, chunks 2–3 = unused (zeros).
   Entry (big-endian 4 bytes): [type][modifier bits][hi][lo]
     type 00 = keyboard (usage in lo, modifiers bitmask in byte 1)
     type 02 = consumer usage (hi,lo)   type 0d = Fn
     type 07 / 08 = built-in keyboard functions (BT, lighting…)
   Matrix index = column*6 + row.
   ===================================================================== */

// ---------- Codes ----------
const CODES=[]; const add=(v,label,cat)=>CODES.push({v,label,cat});
const KB = u => u;                       // 00 00 00 uu
const MOD = u => (1<<(u-0xE0))<<16;      // 00 mm 00 00
const CON = u => (0x02<<24)|u;           // 02 00 hh ll
"ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").forEach((c,i)=>add(KB(4+i),c,"Letters"));
"1234567890".split("").forEach((c,i)=>add(KB(0x1E+i),c,"Numbers"));
[[0x28,"Enter"],[0x29,"Esc"],[0x2A,"Bksp"],[0x2B,"Tab"],[0x2C,"Space"],[0x2D,"-"],[0x2E,"="],[0x2F,"["],[0x30,"]"],[0x31,"\\"],[0x33,";"],[0x34,"'"],[0x35,"`"],[0x36,","],[0x37,"."],[0x38,"/"],[0x39,"Caps"],[0x64,"ISO \\"]].forEach(a=>add(KB(a[0]),a[1],"Symbols"));
for(let i=1;i<=12;i++) add(KB(0x39+i),"F"+i,"F-keys");
for(let i=13;i<=24;i++) add(KB(0x68+i-13),"F"+i,"F-keys");
[[0x46,"PrtSc"],[0x47,"ScrLk"],[0x48,"Pause"],[0x49,"Ins"],[0x4A,"Home"],[0x4B,"PgUp"],[0x4C,"Del"],[0x4D,"End"],[0x4E,"PgDn"],[0x4F,"→"],[0x50,"←"],[0x51,"↓"],[0x52,"↑"],[0x65,"Menu"]].forEach(a=>add(KB(a[0]),a[1],"Navigation"));
[[0xE0,"L Ctrl"],[0xE1,"L Shift"],[0xE2,"L Alt"],[0xE3,"L Win"],[0xE4,"R Ctrl"],[0xE5,"R Shift"],[0xE6,"R Alt"],[0xE7,"R Win"]].forEach(a=>add(MOD(a[0]),a[1],"Modifiers"));
[[0x53,"NumLk"],[0x54,"KP /"],[0x55,"KP *"],[0x56,"KP -"],[0x57,"KP +"],[0x58,"KP Enter"],[0x59,"KP 1"],[0x5A,"KP 2"],[0x5B,"KP 3"],[0x5C,"KP 4"],[0x5D,"KP 5"],[0x5E,"KP 6"],[0x5F,"KP 7"],[0x60,"KP 8"],[0x61,"KP 9"],[0x62,"KP 0"],[0x63,"KP ."]].forEach(a=>add(KB(a[0]),a[1],"Numpad"));
[[0xCD,"Play/Pause"],[0xB5,"Next"],[0xB6,"Prev"],[0xB7,"Stop"],[0xE2,"Mute"],[0xE9,"Vol +"],[0xEA,"Vol −"],[0x6F,"Bright +"],[0x70,"Bright −"],[0x223,"Browser Home"],[0x192,"Calculator"],[0x18A,"Mail"],[0x221,"Search"]].forEach(a=>add(CON(a[0]),a[1],"Media"));
add(0x0d000000,"Fn","Special");
add(0x0d010000,"FN2","Special");
[[0x08000000,"Light effect"],[0x08020000,"Light color"],[0x08030100,"Light +"],[0x08030200,"Light −"],[0x08040100,"Speed +"],[0x08040200,"Speed −"],[0x07000001,"Win Lock"],[0x0700001c,"Knob light"]].forEach(a=>add(a[0],a[1],"Keyboard"));
add(0,"Disabled","Special");
const BY_V=new Map(CODES.map(c=>[c.v>>>0,c]));
const MODNAMES=["Ctrl","Shift","Alt","Win","R Ctrl","R Shift","R Alt","R Win"];
const MACMOD={"L Win":"L Cmd","R Win":"R Cmd","L Alt":"L Opt","R Alt":"R Opt","Win":"Cmd","Alt":"Opt"};
const h2=n=>n.toString(16).padStart(2,"0");
function labelOf(v){
  v=v>>>0;
  const c=BY_V.get(v); if(c) return macify(c.label);
  if(SYS[v]) return SYS[v];
  const t=v>>>24, m=(v>>16)&255, u=v&0xffff;
  if(v===0x00040029) return mode==="mac"?"Cmd+Esc":"Alt+Esc";
  if(t===0 && m){ const mods=MODNAMES.filter((_,i)=>m&(1<<i)).map(macify).join("+"); const k=BY_V.get(u); return u? mods+"+"+(k?k.label:"0x"+h2(u)) : mods; }
  if(t===2) return "Media "+u.toString(16);
  if(t===7) return "⚙ Sys "+h2(v&255);
  if(t===8) return "⚙ "+[(v>>16)&255,(v>>8)&255].map(h2).join("·");
  return "0x"+(v>>>0).toString(16).padStart(8,"0");
}
// Built-in functions, named from the LEOBOG Hi75C Pro manual
const SYS={0x07000004:"Reset (hold)",0x07000008:"2.4G",0x07000005:"BT 1",0x07000006:"BT 2",0x07000007:"BT 3",
  0x07000019:"Android mode",0x07000018:"Windows mode",0x0700001a:"Mac mode",0x0700001b:"iOS mode",
  0x07000001:"Win Lock",0x0700001c:"Knob light",0x0700001d:"Knob Mode",0x0700000a:"No effect",0x07000011:"No effect",
  0x08000000:"Light effect",0x08020000:"Light color",0x08030100:"Light +",0x08030200:"Light −",0x08040100:"Speed +",0x08040200:"Speed −"};
function isSpecial(v){ const t=v>>>24; return t===7||t===8; }
function macify(l){ return mode==="mac" && MACMOD[l] ? MACMOD[l] : l; }
const CATS=["All",...new Set(CODES.map(c=>c.cat))];

// ---------- Matrix + physical layout ----------
// each key: [matrixIndex, width]; null entries = gaps
const LAYOUT=[
  [[0,1],[null,.25],[12],[18],[24],[30],[null,.25],[36],[42],[48],[54],[null,.25],[60],[66],[72],[78],[null,1.5],[84,1,"knob"]],
  [[1],[7],[13],[19],[25],[31],[37],[43],[49],[55],[61],[67],[73],[79,2],[null,.25],[85]],
  [[2,1.5],[8],[14],[20],[26],[32],[38],[44],[50],[56],[62],[68],[74],[80,1.5],[null,.25],[86]],
  [[3,1.75],[9],[15],[21],[27],[33],[39],[45],[51],[57],[63],[69],[81,2.25],[null,.25],[87]],
  [[4,2.25],[10],[16],[22],[28],[34],[40],[46],[52],[58],[64],[70,1.75],[null,.25],[82],[88]],
  [[5,1.25],[11,1.25],[17,1.25],[35,6.25],[53],[59],[65],[null,.25],[77],[83],[89]],
];
// Factory tables (from LEOBOG ONE capture, Windows mode)
const FACT_BASE=[41,53,43,57,131072,65536,0,30,20,4,29,524288,58,31,26,22,27,262144,59,32,8,7,6,0,60,33,21,9,25,0,61,34,23,10,5,44,62,35,28,11,17,0,63,36,24,13,16,0,64,37,12,14,54,4194304,65,38,18,15,55,218103808,66,39,19,51,56,1048576,67,45,47,52,2097152,0,68,46,48,0,0,80,69,42,49,40,82,81,117440541,76,77,75,78,79];
const FACT_FN=[117440516,117440520,134348800,0,0,0,0,117440517,117440537,0,0,117440513,33554544,117440518,117440536,0,0,0,33554543,117440519,117440538,0,0,0,262187,0,117440539,0,0,0,262185,0,0,117440522,117440529,0,134414848,0,0,0,0,0,134414592,0,70,0,0,0,33554614,0,71,0,0,0,33554637,0,72,0,0,0,33554613,0,0,0,0,0,33554658,0,0,0,0,0,33554666,0,0,0,0,134480384,33554665,117440540,134217728,0,134414592,134414848,0,73,74,0,0,134480128];
const PHYS = FACT_BASE.map(v=>labelOfRaw(v));
function labelOfRaw(v){ const c=BY_V.get(v>>>0); return c?c.label:(v===117440541?"Knob":"?"); }

// ---------- Modes ----------
// modeByte: Windows confirmed from capture (01). Mac/Android pending captures.
// One keymap shared by all OS modes (confirmed: Win & Mac captures identical,
// and a Mac-mode write also applied in Windows mode). Firmware does the Mac swaps.
const FN2=0x0d010000;
const MODES=[{id:"win",name:"Hi75C",byte:0x01,ok:true}];
// chunk 0 Default · 1 FN1 · 2 FN2 · 3 Tap (tap action for dual-role keys)
const LAYERS=["Default","FN1","FN2","Tap"];

// ---------- State ----------
// ---------- Input hardening ----------
// Only key codes this app knows (picker codes, built-in functions, factory values) may ever be written.
const ALLOWED=new Set([...CODES.map(c=>c.v>>>0),...Object.keys(SYS).map(k=>Number(k)>>>0),...FACT_BASE.map(v=>v>>>0),...FACT_FN.map(v=>v>>>0)]);
const BAD_NAMES=new Set(["__proto__","constructor","prototype"]);
function cleanName(n){ n=String(n==null?"":n).replace(/[\u0000-\u001f\u007f]/g,"").trim().slice(0,40); return n&&!BAD_NAMES.has(n)?n:null; }
function cleanLayer(o){ const out={}; if(o&&typeof o==="object"&&!Array.isArray(o)) for(const [k,v] of Object.entries(o)){
  const i=Number(k), n=Number(v); if(Number.isInteger(i)&&i>=0&&i<90&&Number.isInteger(n)&&n>=0&&n<=0xFFFFFFFF&&ALLOWED.has(n>>>0)) out[i]=n>>>0; } return out; }
function cleanProfile(p){ const out=blank(); MODES.forEach(m=>{ const a=p&&Array.isArray(p[m.id])?p[m.id]:[]; out[m.id]=[cleanLayer(a[0]),cleanLayer(a[1]),cleanLayer(a[2]),{}]; }); return out; }
let state=load()||{current:"Default",profiles:{Default:blank()}};
norm();
let mode="win", layer=0, selected=null, testMode=false, cat="All";
function blank(){ const p={}; MODES.forEach(m=>p[m.id]=[{},{},{},{}]); return p; }
function norm(){ Object.values(state.profiles).forEach(p=>MODES.forEach(m=>{ p[m.id]=p[m.id]||[]; while(p[m.id].length<4) p[m.id].push({}); })); }
function prof(){ return state.profiles[state.current]; }
function cur(){ return prof()[mode][layer]; }
function save(){ try{ localStorage.setItem("hi75c-remap-v6",JSON.stringify(state)); }catch(e){} }
function load(){ try{
  const raw=JSON.parse(localStorage.getItem("hi75c-remap-v6")); if(!raw||typeof raw.profiles!=="object") return null;
  const profiles={}; for(const [n,p] of Object.entries(raw.profiles)){ const c=cleanName(n); if(c) profiles[c]=cleanProfile(p); }
  const names=Object.keys(profiles); if(!names.length) return null;
  return {current:names.includes(raw.current)?raw.current:names[0],profiles};
}catch(e){ return null; } }
function factory(idx,l=layer){ return l===0?FACT_BASE[idx]>>>0 : l===1?FACT_FN[idx]>>>0 : 0; }
function valueAt(idx,l=layer,m=mode){
  const o=prof()[m][l][idx]; if(o!==undefined) return o>>>0;
  // a key set to FN2 in Default is mirrored into FN1 and FN2 (same as LEOBOG ONE)
  if((l===1||l===2) && prof()[m][0][idx]===FN2) return FN2;
  return factory(idx,l);
}

// ---------- Keyboard render ----------
const ACCENT=new Set([0,35,79,81,77,82,83,89]); // Esc, Space, Bksp, Enter, arrows — like the real colorway
const kbEl=document.getElementById("kb");
function renderKB(){
  kbEl.innerHTML="";
  LAYOUT.forEach((row,r)=>{
    const rowEl=document.createElement("div"); rowEl.className="row"+(r===0?" gap":"");
    row.forEach(k=>{
      const w=k[1]||1;
      if(k[0]===null){ const g=document.createElement("div"); g.style.width=`calc(var(--u)*${w} + ${w-1}*var(--gap))`; g.style.flexShrink="0"; rowEl.appendChild(g); return; }
      const idx=k[0], v=valueAt(idx), changed=v!==factory(idx);
      const d=document.createElement("button"); d.type="button";
      d.className="k"+(ACCENT.has(idx)?" acc":"")+((layer>0&&v===0)?" empty":"")+(k[2]==="knob"?" knob":"")+(changed?" changed":"")+(selected===idx?" sel":"")+(isSpecial(v)?" special":"");
      d.dataset.idx=idx; d.dataset.phys=PHYS[idx];
      d.style.width=`calc(var(--u)*${w} + ${w-1}*var(--gap))`;
      const txt = (layer>0 && v===0) ? "·" : (k[2]==="knob" && v===117440541 ? "●" : labelOf(v));
      const orig = changed ? `<span class="orig">${esc(macify(PHYS[idx]))}</span>` : (layer>0?`<span class="orig">${esc(macify(PHYS[idx]))}</span>`:"");
      d.innerHTML=`${orig}<span class="lbl">${esc(txt)}</span>`;
      d.title=`${PHYS[idx]} — matrix ${idx}`;
      if(paintMode()){ const c=light.keys[idx]||[0,0,0]; if(c[0]||c[1]||c[2]){ d.style.background=`rgb(${c[0]},${c[1]},${c[2]})`; d.classList.add("lit"); } }
      d.onclick=()=>{ if(paintMode()){ light.keys[idx]=hexToRgb(document.getElementById("sdColor").value); saveLight(); renderKB(); } else select(idx); };
      rowEl.appendChild(d);
    });
    kbEl.appendChild(rowEl);
  });
}
function esc(s){ return String(s).replace(/[&<>"]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m])); }
function select(idx){
  selected=idx; const v=valueAt(idx);
  document.getElementById("selInfo").innerHTML=(LANG==="en"?`Key: <b>${esc(macify(PHYS[idx]))}</b> — layer ${LAYERS[layer]}<br>Current function: <b>${esc(layer>0&&v===0?"(none)":labelOf(v))}</b>`:`الزرار: <b>${esc(macify(PHYS[idx]))}</b> — طبقة ${LAYERS[layer]}<br>الوظيفة الحالية: <b>${esc(layer>0&&v===0?"(مفيش)":labelOf(v))}</b>`);
  renderKB();
}
function assign(v){
  if(selected===null){ toast(T("اختار زرار من الكيبورد الأول")); return; }
  v=v>>>0;
  if(v===factory(selected)) delete cur()[selected]; else cur()[selected]=v;
  save(); select(selected); renderChanges(); updateWriteBtn();
}

// ---------- Tabs ----------
function renderTabs(){
  document.getElementById("modeTabs").style.display="none";
  const le=document.getElementById("layerTabs"); le.innerHTML="";
  LAYERS.forEach((n,i)=>{ const t=document.createElement("button"); t.type="button"; t.setAttribute("role","tab");
    if(i===3){ t.className="tab"; t.disabled=true; t.style.opacity=".45"; t.style.cursor="not-allowed"; t.innerHTML=esc(n)+'<span class="soon">'+T("(مش شغالة)")+'</span>'; t.title=T("اتجربت ومش بتعمل أي حاجة على الـ Hi75C Pro"); le.appendChild(t); return; }
    t.className="tab"+(i===layer?" active":""); t.textContent=n; t.onclick=()=>{layer=i; refresh();}; le.appendChild(t); });
  const hints=[T("اللي الزراير بتعمله لما تدوسها عادي."),T("اللي الزراير بتعمله وانت ماسك Fn. الزرار اللي عليه «·» مش بيعمل حاجة في الطبقة دي."),T("اللي الزراير بتعمله وانت ماسك زرار FN2. عشان تستخدمها خلي زرار في Default يبقى FN2 (من Special)."),""];
  document.getElementById("layerHint").textContent=hints[layer];
  const m=MODES.find(x=>x.id===mode); const b=document.getElementById("modeBanner");
  b.className="note"; b.innerHTML=LANG==="en"?`<b>Ready to write.</b> One keymap is shared by all modes (Windows, Mac, Android, iOS). In Mac mode the keyboard itself swaps Win/Alt and flips the F-row. Change what you want, then click “Write to keyboard”.`:`<b>جاهز للكتابة.</b> الكي ماب واحد لكل المودات (Windows وMac وAndroid وiOS). في مود Mac الكيبورد نفسه بيبدّل Win وAlt وبيقلب صف F. غيّر اللي انت عاوزه، وبعدين دوس «اكتب على الكيبورد».`;
}

// ---------- Picker ----------
function renderCats(){ const el=document.getElementById("cats"); el.innerHTML=""; CATS.forEach(c=>{ const b=document.createElement("button"); b.className="cat"+(c===cat?" active":""); b.textContent=c; b.onclick=()=>{cat=c; renderCats(); renderGrid();}; el.appendChild(b); }); }
function renderGrid(){
  const q=document.getElementById("search").value.trim().toLowerCase();
  const el=document.getElementById("grid"); el.innerHTML="";
  CODES.filter(c=>(cat==="All"||c.cat===cat)&&(!q||c.label.toLowerCase().includes(q)||macify(c.label).toLowerCase().includes(q))).forEach(c=>{ const o=document.createElement("button"); o.className="opt"; o.textContent=macify(c.label); o.onclick=()=>assign(c.v); el.appendChild(o); });
}
document.getElementById("search").oninput=renderGrid;

// ---------- Changes ----------
function renderChanges(){
  const lines=[];
  MODES.forEach(m=>prof()[m.id].forEach((lay,i)=>Object.entries(lay).forEach(([idx,v])=>{
    lines.push(`[${LAYERS[i]}] ${PHYS[idx]}  →  ${labelOf(v)}   (0x${(v>>>0).toString(16).padStart(8,"0")})`);
  })));
  document.getElementById("changes").textContent=lines.length?lines.join("\n"):T("مفيش تغييرات لسه — كل الزراير على الإعدادات الأصلية.");
}

