document.getElementById("btnNewProfile").onclick=()=>openModal(T("اسم البروفايل الجديد"),"","Gaming",false,t=>{ const n=cleanName(t.split("\n")[0]); if(!n){ toast(T("ده مش بروفايل صالح")); return; } state.profiles[n]=blank(); state.current=n; save(); refresh(); });
document.getElementById("btnExport").onclick=()=>openModal("Export",T("انسخ النص ده واحفظه."),JSON.stringify({app:"hi75c-remap",v:3,name:state.current,map:prof()},null,2),true);
document.getElementById("btnImport").onclick=()=>openModal("Import",T("الصق البروفايل هنا."),"",false,t=>{ try{ const d=JSON.parse(t); if(!d||!d.map||!Array.isArray(d.map.win)) throw 0; const n=cleanName(d.name)||"Imported"; state.profiles[n]=cleanProfile(d.map); state.current=n; save(); refresh(); toast(T("اتعمل Import")); }catch(e){ toast(T("ده مش بروفايل صالح")); } });
document.getElementById("btnResetKey").onclick=()=>{ if(selected===null) return; delete cur()[selected]; save(); select(selected); renderChanges(); };
