// ---------- Modal / toast ----------
let mCb=null;
function openModal(title,body,text,readonly,cb,showText=true){ document.getElementById("mTitle").textContent=title; document.getElementById("mBody").textContent=body||""; const t=document.getElementById("mText"); t.style.display=showText?"block":"none"; t.value=text||""; t.readOnly=!!readonly; mCb=cb||null; document.getElementById("mCopy").style.display=showText?"":"none"; document.getElementById("modal").classList.add("show"); }
document.getElementById("mOk").onclick=()=>{ const v=document.getElementById("mText").value; document.getElementById("modal").classList.remove("show"); if(mCb) mCb(v); };
document.getElementById("mCancel").onclick=()=>document.getElementById("modal").classList.remove("show");
document.getElementById("mCopy").onclick=()=>copy(document.getElementById("mText").value);
function copy(t){ navigator.clipboard.writeText(t).then(()=>toast(T("اتنسخ")),()=>toast(T("النسخ اترفض — انسخ يدوي"))); }
function toast(m){ const t=document.getElementById("toast"); t.textContent=m; t.classList.add("show"); clearTimeout(t._h); t._h=setTimeout(()=>t.classList.remove("show"),2200); }

// ---------- Test mode ----------
const EVCODE={Escape:0x29,Backquote:0x35,Minus:0x2d,Equal:0x2e,Backspace:0x2a,Tab:0x2b,BracketLeft:0x2f,BracketRight:0x30,Backslash:0x31,CapsLock:0x39,Semicolon:0x33,Quote:0x34,Enter:0x28,Comma:0x36,Period:0x37,Slash:0x38,Space:0x2c,Delete:0x4c,PageUp:0x4b,PageDown:0x4e,Home:0x4a,End:0x4d,Insert:0x49,ArrowUp:0x52,ArrowDown:0x51,ArrowLeft:0x50,ArrowRight:0x4f,ControlLeft:MOD(0xE0),ShiftLeft:MOD(0xE1),AltLeft:MOD(0xE2),MetaLeft:MOD(0xE3),ControlRight:MOD(0xE4),ShiftRight:MOD(0xE5),AltRight:MOD(0xE6),MetaRight:MOD(0xE7)};
function evToV(code){ if(EVCODE[code]!==undefined) return EVCODE[code]>>>0; let m; if(m=code.match(/^Key([A-Z])$/)) return 4+m[1].charCodeAt(0)-65; if(m=code.match(/^Digit(\d)$/)) return m[1]==="0"?0x27:0x1d+ +m[1]; if(m=code.match(/^F(\d+)$/)){ const n=+m[1]; return n<=12?0x39+n:0x68+n-13; } return null; }
document.getElementById("btnTest").onclick=()=>{ testMode=!testMode; document.getElementById("btnTest").textContent=testMode?T("إيقاف الاختبار"):T("وضع الاختبار"); document.getElementById("testHint").hidden=!testMode; };
function flash(ev,down){
  if(!testMode) return;
  if(document.activeElement&&/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)) return;
  ev.preventDefault();
  const v=evToV(ev.code); if(down) logLine(`key ${ev.code}`);
  if(v===null) return;
  // highlight every key whose CURRENT base mapping sends this code
  document.querySelectorAll(".k").forEach(e=>{ if(valueAt(+e.dataset.idx,0)===v) e.classList.toggle("pressed",down); });
}
addEventListener("keydown",e=>flash(e,true)); addEventListener("keyup",e=>flash(e,false));

// ---------- WebHID ----------
const logEl=document.getElementById("log");
function logLine(s){ logEl.textContent+=`[${new Date().toLocaleTimeString("en-GB")}] ${s}\n`; logEl.scrollTop=logEl.scrollHeight; }
document.getElementById("btnClearLog").onclick=()=>logEl.textContent="";
document.getElementById("btnCopyLog").onclick=()=>copy(logEl.textContent);
const hex=(n,w=4)=>"0x"+n.toString(16).padStart(w,"0");
let devices=[], cfgDev=null;
document.getElementById("btnConnect").onclick=async()=>{
  if(!("hid" in navigator)){ toast(T("افتح الصفحة في Chrome أو Edge")); return; }
  try{
    const picked=await navigator.hid.requestDevice({filters:[{vendorId:0x258a,productId:0x010c}]});
    if(!picked.length) return;
    const all=await navigator.hid.getDevices(), p=picked[0];
    devices=all.filter(d=>d.vendorId===p.vendorId&&d.productId===p.productId);
    cfgDev=null;
    for(const d of devices){
      if(!d.opened){ try{ await d.open(); }catch(e){ logLine("open failed: "+e.message); } }
      if(d.collections.some(c=>(c.featureReports||[]).some(r=>r.reportId===6))) cfgDev=d;
      d.oninputreport=ev=>{ if(ev.reportId===6) logLine(`IN id=6 ${[...new Uint8Array(ev.data.buffer)].map(b=>h2(b)).join(" ")}`); };
    }
    if(cfgDev){ const model=await identify(cfgDev).catch(e=>{ logLine("identify failed: "+e.message); return -1; });
      logLine("model id: "+(model<0?"unknown":"0x"+h2(model)));
      if(model>=0 && model!==0xA3){ cfgDev=null; toast(T("ده مش Hi75C Pro — الكتابة اتقفلت عشان الأمان")); logLine("Not a Hi75C Pro (expected 0xa3). Writing disabled."); } }
    setConnected(true,p); renderDevice();
    if(!cfgDev) logLine("Feature report 6 not found on this device — wrong device or wireless mode?");
  }catch(e){ logLine("connect error: "+e.message); toast(T("التوصيل فشل — بص في الـ Log")); }
};
navigator.hid&&navigator.hid.addEventListener("disconnect",e=>{ if(devices.includes(e.device)){ devices=[]; cfgDev=null; setConnected(false); renderDevice(); logLine("disconnected"); }});
// Same query LEOBOG ONE sends on start; byte 13 of the reply is the model (Hi75C Pro = 0xA3).
async function identify(d){
  const req=new Uint8Array(519); req.set([0x82,0x01,0x00,0x01,0x00,0x06,0x00]);
  await d.sendFeatureReport(6,req); await sleep(30);
  const dv=await d.receiveFeatureReport(6); let b=new Uint8Array(dv.buffer,dv.byteOffset,dv.byteLength);
  if(b[0]===0x82){ const t=new Uint8Array(b.length+1); t[0]=6; t.set(b,1); b=t; }
  return (b[0]===0x06&&b[1]===0x82&&b.length>13)?b[13]:-1;
}
// Keymap/lighting writes get the HID channel to themselves (music frames pause).
let exclusive=false;
async function takeChannel(){ if(music) stopMusic(); exclusive=true; while(sending) await sleep(10); }
function releaseChannel(){ exclusive=false; }
function setConnected(on,d){ document.getElementById("dot").classList.toggle("on",on); document.getElementById("status").textContent=on?`${d.productName} (${hex(d.vendorId)}:${hex(d.productId)})`:"Not connected"; updateWriteBtn(); }
function updateWriteBtn(){ ["lRead","lApply","mStart","mTest"].forEach(id=>{ const e=document.getElementById(id); if(e) e.disabled=!cfgDev; }); const m=MODES.find(x=>x.id===mode); const b=document.getElementById("btnWrite"); b.disabled=!(cfgDev&&m.ok); b.title=!cfgDev?T("وصّل الكيبورد الأول"):(!m.ok?"المود ده لسه مستني تسجيلة":""); }
function renderDevice(){
  const el=document.getElementById("devInfo"); document.getElementById("devEmpty").style.display=devices.length?"none":"block";
  if(!devices.length){ el.innerHTML=""; return; }
  let h=`<table><tr><th>Usage Page</th><th>Usage</th><th>Input</th><th>Feature</th></tr>`;
  devices.forEach(d=>d.collections.forEach(c=>{ const v=c.usagePage>=0xFF00; const ids=k=>(c[k]||[]).map(r=>r.reportId).join(", ")||"–"; h+=`<tr><td class="${v?"vendor":""}">${hex(c.usagePage)}</td><td>${hex(c.usage)}</td><td>${ids("inputReports")}</td><td>${ids("featureReports")}</td></tr>`; }));
  el.innerHTML=h+"</table>"+`<p class="muted">${cfgDev?T("قناة الإعدادات (Feature 6) موجودة — الكتابة متاحة."):T("قناة الإعدادات مش ظاهرة.")}</p>`;
}

// Build the 4 feature-report payloads (519 bytes each, report id passed separately)
function buildChunks(modeId){
  const m=MODES.find(x=>x.id===modeId); const chunks=[];
  for(let c=0;c<4;c++){
    const buf=new Uint8Array(519);           // = full report bytes 1..519
    buf[0]=0x03; buf[1]=c; buf[2]=0x00; buf[3]=m.byte; buf[4]=0; buf[5]=0; buf[6]=0x02;
    for(let i=0;i<90;i++){
      const v=valueAt(i,c,modeId); const o=7+4*i;
      buf[o]=(v>>>24)&255; buf[o+1]=(v>>>16)&255; buf[o+2]=(v>>>8)&255; buf[o+3]=v&255;
    }
    buf[517]=0x5a; buf[518]=0xa5;
    chunks.push(buf);
  }
  return chunks;
}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
document.getElementById("btnWrite").onclick=()=>{
  const m=MODES.find(x=>x.id===mode);
  const n=prof()[mode].reduce((a,l)=>a+Object.keys(l).length,0);
  openModal(T("كتابة الكي ماب على الكيبورد"),LANG==="en"?`The Default, FN1 and FN2 layers will be written to the keyboard with ${n} change(s) from factory, replacing what is stored on it. Make sure the keyboard is connected by cable and the LEOBOG app is closed.`:(`هيتكتب على الكيبورد طبقة Default وFN1 وFN2، وفيهم ${n} تغيير عن الأصل، وده بيستبدل اللي متخزن عليه. اتأكد إن الكيبورد متوصل بالكابل وإن برنامج LEOBOG مقفول.`),
    "",false,()=>doWrite(m),false);
};
async function doWrite(m){
  const b=document.getElementById("btnWrite"); b.disabled=true; b.textContent=T("بيكتب…");
  await takeChannel();
  try{
    const chunks=buildChunks(m.id);
    for(let c=0;c<4;c++){
      await cfgDev.sendFeatureReport(6,chunks[c]);
      logLine(`SET id=6 chunk ${c}: 06 ${[...chunks[c].slice(0,7)].map(h2).join(" ")} …`);
      await sleep(90);
    }
    toast(T("اتكتب على الكيبورد ✓ — جرّب الزراير")); logLine("write OK");
  }catch(e){ logLine("write error: "+e.message); toast(T("الكتابة فشلت — بص في الـ Log")); }
  releaseChannel(); b.textContent=T("اكتب على الكيبورد"); updateWriteBtn();
}

/* ---------------- Lighting ----------------
   Decoded from LEOBOG ONE capture 06:
   read : SET f6 [06 84 00 00 01 00 80 00 …]  → GET f6 returns 136 B config
   write: same config with byte1 = 0x04 (rest of 520 B zero)
     cfg[17] = custom flag (1 = Self-define)   cfg[18] = effect id
     cfg[64+2*id] = brightness 0–4             cfg[65+2*id] = speed<<4 | colorIdx
   self-define colors: SET f6 [06 06 00 00 01 00 7a 01] + R[126] G[126] B[126]
     (planar, LED index = matrix index) */
const EFFECTS=[[1,"Fixed on"],[2,"Respire"],[3,"Rainbow"],[4,"Flash away"],[5,"Raindrops"],[6,"Ripples shining"],[7,"Stars twinkle"],[8,"Retro snake"],[9,"Neon stream"],[10,"Reaction"],[11,"Sine wave"],[12,"Rotating windmill"],[13,"Colorful waterfall"],[14,"Blossoming"],[0x15,"Self-define"]];
const PALETTE=[[255,0,0],[0,255,0],[0,0,255],[255,255,0],[255,0,255],[0,255,255],[255,255,255],null];
const SD_DEFAULT=(()=>{ const k={}; [1,9,14,15,21,77,82,83,89].forEach(i=>k[i]=[255,255,255]); return k; })();
let light=loadLight(), lightCfg=null;
const clampInt=(v,lo,hi,d)=>{ v=Number(v); return Number.isInteger(v)?Math.min(hi,Math.max(lo,v)):d; };
function cleanLight(l){
  const out={effect:1,bright:4,speed:4,color:7,keys:{...SD_DEFAULT}}; if(!l||typeof l!=="object") return out;
  if(EFFECTS.some(e=>e[0]===l.effect)) out.effect=l.effect;
  out.bright=clampInt(l.bright,0,4,4); out.speed=clampInt(l.speed,0,4,4); out.color=clampInt(l.color,0,7,7);
  if(l.keys&&typeof l.keys==="object"){ out.keys={}; for(const [k,c] of Object.entries(l.keys)){ const i=Number(k);
    if(Number.isInteger(i)&&i>=0&&i<126&&Array.isArray(c)&&c.length===3) out.keys[i]=c.map(x=>clampInt(x,0,255,0)); } }
  return out;
}
function loadLight(){ try{ return cleanLight(JSON.parse(localStorage.getItem("hi75c-light"))); }catch(e){ return cleanLight(null); } }
function saveLight(){ try{ localStorage.setItem("hi75c-light",JSON.stringify(light)); }catch(e){} }
let painting=false;
function paintMode(){ return typeof light!=="undefined" && light.effect===0x15 && painting; }
function hexToRgb(h){ return [1,3,5].map(i=>parseInt(h.substr(i,2),16)); }
function buildConfigWrite(cfg,l){
  l=cleanLight(l);
  const out=new Uint8Array(520); out.set(cfg.slice(0,136)); out[0]=0x06; out[1]=0x04;
  if(l.effect===0x15){ out[17]=1; out[18]=0x15; }
  else { out[17]=0; out[18]=l.effect; out[64+2*l.effect]=l.bright; out[65+2*l.effect]=((l.speed&15)<<4)|(l.color&15); }
  return out;
}
function buildSelfDefine(keys){
  const out=new Uint8Array(520); out.set([0x06,0x06,0,0,0x01,0,0x7a,0x01]);
  for(let i=0;i<126;i++){ const c=keys[i]||[0,0,0]; out[8+i]=c[0]; out[134+i]=c[1]; out[260+i]=c[2]; }
  return out;
}
async function readConfig(){
  const req=new Uint8Array(519); req.set([0x84,0,0,0x01,0,0x80,0x00]);
  await cfgDev.sendFeatureReport(6,req); await sleep(30);
  const dv=await cfgDev.receiveFeatureReport(6);
  let b=new Uint8Array(dv.buffer,dv.byteOffset,dv.byteLength);
  if(b[0]===0x84){ const t=new Uint8Array(b.length+1); t[0]=6; t.set(b,1); b=t; }
  if(b[0]!==0x06||b[1]!==0x84) throw new Error("unexpected config reply: "+[...b.slice(0,8)].map(h2).join(" "));
  return b.slice(0,136);
}
function renderLight(){
  const sel=document.getElementById("lEffect");
  if(!sel.options.length) EFFECTS.forEach(([id,n])=>{ const o=document.createElement("option"); o.value=id; o.textContent=n; sel.appendChild(o); });
  sel.value=light.effect;
  document.getElementById("lBright").value=light.bright; document.getElementById("lSpeed").value=light.speed;
  const sd=light.effect===0x15; if(!sd) painting=false;
  document.querySelectorAll(".lrow").forEach(e=>e.style.visibility=sd?"hidden":"visible");
  document.getElementById("sdBox").hidden=!sd;
  const sw=document.getElementById("lColors"); sw.innerHTML="";
  PALETTE.forEach((c,i)=>{ const d=document.createElement("div"); d.title=c?`rgb(${c})`:"Colorful";
    d.style.background=c?`rgb(${c})`:"conic-gradient(red,yellow,lime,cyan,blue,magenta,red)";
    if(i===light.color) d.classList.add("on"); d.onclick=()=>{ light.color=i; saveLight(); renderLight(); }; sw.appendChild(d); });
  renderKB();
}
document.getElementById("lEffect").onchange=e=>{ light.effect=+e.target.value; if(lightCfg&&light.effect!==0x15){ light.bright=lightCfg[64+2*light.effect]&7; light.speed=lightCfg[65+2*light.effect]>>4; light.color=lightCfg[65+2*light.effect]&15; } saveLight(); renderLight(); };
document.getElementById("lBright").oninput=e=>{ light.bright=+e.target.value; saveLight(); };
document.getElementById("lSpeed").oninput=e=>{ light.speed=+e.target.value; saveLight(); };
document.getElementById("sdAll").onclick=()=>{ const c=hexToRgb(document.getElementById("sdColor").value); for(let i=0;i<90;i++) light.keys[i]=c; saveLight(); renderKB(); };
document.getElementById("sdPaint").onclick=()=>{ painting=!painting; document.getElementById("sdPaint").textContent=painting?T("وقّف التلوين"):T("ابدأ التلوين"); renderKB(); };
document.getElementById("sdClear").onclick=()=>{ light.keys={}; saveLight(); renderKB(); };
document.getElementById("lRead").onclick=async()=>{
  await takeChannel();
  try{ lightCfg=await readConfig(); const id=lightCfg[18];
    if(EFFECTS.some(e=>e[0]===id)) light.effect=id;
    if(id!==0x15){ light.bright=lightCfg[64+2*id]&7; light.speed=lightCfg[65+2*id]>>4; light.color=lightCfg[65+2*id]&15; }
    saveLight(); renderLight(); document.getElementById("lStatus").textContent=T("اتقرت الإعدادات من الكيبورد ✓"); logLine("config: "+[...lightCfg.slice(8,72)].map(h2).join(" "));
  }catch(e){ logLine("read config error: "+e.message); toast(T("القراية فشلت — بص في الـ Log")); }
  releaseChannel();
};
document.getElementById("lApply").onclick=async()=>{
  const b=document.getElementById("lApply"); b.disabled=true;
  await takeChannel();
  try{
    if(light.effect===0x15){ const sd=buildSelfDefine(light.keys); await cfgDev.sendFeatureReport(6,sd.slice(1)); logLine("SET self-define colors"); await sleep(80); }
    const cfg=await readConfig(); const out=buildConfigWrite(cfg,light);
    await cfgDev.sendFeatureReport(6,out.slice(1)); lightCfg=out.slice(0,136); lightCfg[1]=0x84;
    logLine(`SET lighting: effect ${light.effect} bright ${light.bright} speed ${light.speed} color ${light.color}`);
    toast(T("الإضاءة اتطبقت ✓"));
  }catch(e){ logLine("lighting error: "+e.message); toast(T("الإضاءة فشلت — بص في الـ Log")); }
  releaseChannel(); b.disabled=false;
};

/* ---------------- Music / Direct mode ----------------
   Direct per-LED colors (from OpenRGB SinowealthKeyboard10c, same VID/PID):
   SET f6 [06 08 00 00 01 00 7a 01] + 126 LEDs × RGB (Format A = triplets).
   Format B (planar R[126] G[126] B[126], like self-define) kept as fallback.
   Keyboard falls back to its own effect ~1 s after the last frame. */
let music=null, sending=false;
function buildDirect(cols){ // cols: Array(126) of [r,g,b]
  const out=new Uint8Array(519); out.set([0x08,0,0,0x01,0,0x7a,0x01]);
  const planar=document.getElementById("mFmt").value==="planar";
  for(let i=0;i<126;i++){ const c=cols[i]||[0,0,0];
    if(planar){ out[7+i]=c[0]; out[133+i]=c[1]; out[259+i]=c[2]; } else { out[7+3*i]=c[0]; out[8+3*i]=c[1]; out[9+3*i]=c[2]; } }
  return out;
}
async function sendDirect(cols){ if(!cfgDev||sending||exclusive) return; sending=true; try{ await cfgDev.sendFeatureReport(6,buildDirect(cols)); }catch(e){ logLine("direct error: "+e.message); stopMusic(); } sending=false; }
function hsv(h,s,v){ const f=n=>{ const k=(n+h/60)%6; return Math.round(255*v*(1-s*Math.max(0,Math.min(k,4-k,1)))); }; return [f(5),f(3),f(1)]; }
function previewDirect(cols){ document.querySelectorAll(".k").forEach(e=>{ const c=cols[+e.dataset.idx]; e.style.background=c&&(c[0]||c[1]||c[2])?`rgb(${c})`:""; }); }
document.getElementById("mTest").onclick=async()=>{
  const cols=[]; cols[0]=[255,0,0]; let n=0;
  const t=setInterval(()=>{ sendDirect(cols); if(++n>25){ clearInterval(t); } },100);
  toast(T("بص على الكيبورد 3 ثواني: Esc لوحده المفروض يبقى أحمر"));
};
async function startMusic(){
  try{
    let stream;
    if(document.getElementById("mSrc").value==="mic") stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});
    else { stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:true}); stream.getVideoTracks().forEach(t=>t.stop()); }
    if(!stream.getAudioTracks().length){ toast(T("مفيش صوت — علّم على Share audio في الشباك")); stream.getTracks().forEach(t=>t.stop()); return; }
    const ctx=new AudioContext(), src=ctx.createMediaStreamSource(stream), an=ctx.createAnalyser();
    an.fftSize=1024; an.smoothingTimeConstant=0.55; src.connect(an);
    const bins=new Uint8Array(an.frequencyBinCount), peaks=new Array(15).fill(0); let hue=0;
    let rings=[], drops=[], bassAvg=0.2, cool=0;
    const addRGB=(cols,i,c,w)=>{ const o=cols[i]||[0,0,0]; cols[i]=[Math.min(255,o[0]+c[0]*w),Math.min(255,o[1]+c[1]*w),Math.min(255,o[2]+c[2]*w)].map(Math.round); };
    music={stream,ctx,timer:null};
    music.timer=setInterval(()=>{
      an.getByteFrequencyData(bins); const gain=+document.getElementById("mGain").value;
      const cols=new Array(126).fill(null);
      // 15 log-spaced bands from ~60 Hz to ~12 kHz
      const ny=ctx.sampleRate/2, lv=[];
      for(let c=0;c<15;c++){ const f0=60*Math.pow(200,c/15), f1=60*Math.pow(200,(c+1)/15);
        let a=Math.floor(f0/ny*bins.length), b=Math.max(a+1,Math.ceil(f1/ny*bins.length)), m=0;
        for(let i=a;i<b&&i<bins.length;i++) m=Math.max(m,bins[i]);
        lv.push(Math.min(1,Math.pow(m/255,1.6)*gain)); }
      hue=(hue+0.6)%360;
      const style=document.getElementById("mStyle").value;
      const bass=(lv[0]+lv[1]+lv[2])/3, energy=lv.reduce((a,b)=>a+b,0)/15;
      bassAvg=bassAvg*0.95+bass*0.05; cool--;
      const beat = bass>0.2 && bass>bassAvg*1.3 && cool<=0; if(beat) cool=6;
      if(style==="wave"){
        if(beat) rings.push({r:0,h:hue,a:1});
        rings.forEach(g=>{ g.r+=0.45; g.a*=0.94; }); rings=rings.filter(g=>g.r<9&&g.a>0.05);
        for(let i=0;i<90;i++){ const c=Math.floor(i/6), r=i%6, d=Math.hypot(c-7,(r-2.5)*0.8);
          rings.forEach(g=>{ const w=Math.exp(-Math.pow(d-g.r,2)*1.5)*g.a; if(w>0.02) addRGB(cols,i,hsv(g.h,1,1),w); }); }
      } else if(style==="rain"){
        const spawn=energy*3; for(let k=0;k<Math.floor(spawn+Math.random());k++) drops.push({c:Math.floor(Math.random()*15),y:0,h:(hue+Math.random()*60)%360,v:0.25+Math.random()*0.2});
        drops.forEach(d=>d.y+=d.v); drops=drops.filter(d=>d.y<6.5);
        drops.forEach(d=>{ const r=Math.floor(d.y); if(r<6) addRGB(cols,d.c*6+r,hsv(d.h,1,1),1); if(r-1>=0&&r-1<6) addRGB(cols,d.c*6+r-1,hsv(d.h,1,1),0.3); });
      } else if(style==="spectrum"){
        for(let c=0;c<15;c++){ const v=0.05+0.95*lv[c]; for(let r=0;r<6;r++) cols[c*6+r]=hsv(c*24,1,v*(r===0?0.7:1)); }
      } else if(style==="pulse"){
        const bass=(lv[0]+lv[1]+lv[2])/3, v=Math.min(1,bass*1.2);
        for(let i=0;i<90;i++) cols[i]=hsv((hue+(Math.floor(i/6)*12))%360,1,0.08+0.92*v);
      } else {
        for(let c=0;c<15;c++){ peaks[c]=Math.max(lv[c],peaks[c]-0.06); const h=Math.round(lv[c]*6);
          for(let r=0;r<6;r++){ const fromBottom=5-r, idx=c*6+r;
            if(fromBottom<h) cols[idx]=hsv((120-fromBottom*24+360)%360,1,1);
            else if(fromBottom===Math.min(5,Math.round(peaks[c]*6))) cols[idx]=[255,255,255]; } }
      }
      sendDirect(cols); previewDirect(cols);
    },40);
    stream.getAudioTracks()[0].onended=stopMusic;
    document.getElementById("mStart").textContent=T("وقّف");
    logLine("music mode started");
  }catch(e){ logLine("audio error: "+e.message); toast(T("مقدرتش أوصل للصوت — بص في الـ Log")); }
}
function stopMusic(){ if(!music) return; clearInterval(music.timer); music.stream.getTracks().forEach(t=>t.stop()); music.ctx.close(); music=null;
  document.getElementById("mStart").textContent=T("ابدأ"); renderKB(); logLine("music mode stopped"); }
document.getElementById("mStart").onclick=()=>music?stopMusic():startMusic();

